let projects=[];let lang=['pt','en','es'].includes(localStorage.getItem('portfolio-language'))?localStorage.getItem('portfolio-language'):'pt';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localized=(v,l)=>typeof v==='string'?v:(v?.[l]||v?.pt||'');
const safeUrl=u=>{if(typeof u!=='string'||!u.trim())return'';try{const x=new URL(u,location.href);return ['http:','https:'].includes(x.protocol)?x.href:''}catch{return''}};
const projectArt=(title='3DEasy',featured=true)=>'<div class="project-art"><strong>'+e(title)+'</strong><small>'+e(featured?copy[lang].featured:copy[lang].selected)+'</small></div>';
const projectUi={
  pt:{site:'Visitar o 3DEasy ↗',case:'Ver detalhes ↗',live:'Aplicativo público',work:'Experiência em produtos',demo:'Contas de demonstração',demoIntro:'Escolha o idioma e entre no aplicativo.',email:'E-mail',password:'Senha',demoPt:'Português (Brasil)',demoEn:'English',real:'Tela real do aplicativo',timer:'Prévia visual baseada na interface do Chronos',next:'Próximo ciclo',focus:'Foco',visual:'Prévia do projeto',note:'Outros projetos entram aqui após seleção e revisão.'},
  en:{site:'Visit 3DEasy ↗',case:'View details ↗',live:'Public app',work:'Product experience',demo:'Demo accounts',demoIntro:'Choose a language and sign in to the app.',email:'Email',password:'Password',demoPt:'Portuguese (Brazil)',demoEn:'English',real:'Actual application screen',timer:'Visual preview based on the Chronos interface',next:'Next cycle',focus:'Focus',visual:'Project preview',note:'Other projects will appear here after selection and review.'},
  es:{site:'Visitar 3DEasy ↗',case:'Ver detalles ↗',live:'Aplicación pública',work:'Experiencia en productos',demo:'Cuentas de demostración',demoIntro:'Elige un idioma e inicia sesión en la aplicación.',email:'Correo',password:'Contraseña',demoPt:'Portugués (Brasil)',demoEn:'Inglés',real:'Pantalla real de la aplicación',timer:'Vista previa visual basada en la interfaz de Chronos',next:'Próximo ciclo',focus:'Concentración',visual:'Vista previa del proyecto',note:'Otros proyectos aparecerán aquí tras su selección y revisión.'}
};
function projectVisual(p,compact=false){
  const u=projectUi[lang],img=safeUrl(p.image);
  if(p.id==='3deasy'&&img){
    const photo=safeUrl(p.gallery?.[0]),mobile=safeUrl(p.gallery?.[1]);
    return `<div class="visual-easy${compact?' compact':''}">${photo?`<img class="easy-photo" src="${e(photo)}" alt="" loading="lazy">`:''}<div class="easy-glow"></div><div class="easy-screen"><div class="window-bar"><span></span><span></span><span></span><b>3DEasy</b></div><img src="${e(img)}" alt="${e(localized(p.imageAlt,lang)||p.title)}" loading="lazy"></div>${mobile&&!compact?`<div class="easy-phone"><span class="phone-notch"></span><img src="${e(mobile)}" alt="" loading="lazy"></div>`:''}<span class="visual-stamp">${e(u.real)}</span></div>`
  }
  if(p.visualType==='timer')return `<div class="visual-chronos${compact?' compact':''}" role="img" aria-label="${e(u.timer)}"><div class="chrono-orbit one"></div><div class="chrono-orbit two"></div><div class="chrono-window"><div class="chrono-toolbar"><strong>◴ Chronos</strong><span>◌ &nbsp; ◴ &nbsp; ⚙</span></div><div class="chrono-display">00<span>:</span>00</div><div class="chrono-line"></div><div class="chrono-foot"><span>${e(u.focus)}</span><strong>25 min</strong></div></div><span class="chrono-badge">${e(u.next)} <strong>25 min</strong></span></div>`;
  if(img)return `<div class="visual-generic"><img src="${e(img)}" alt="${e(localized(p.imageAlt,lang)||p.title)}" loading="lazy"></div>`;
  return projectArt(p.title,p.featured)
}
function projectActions(p,compact=false){
  const t=copy[lang],u=projectUi[lang],app=safeUrl(p.appUrl),source=safeUrl(p.sourceUrl);
  return `<div class="showcase-actions">${compact?`<a class="case-link" href="#project-${e(p.id)}">${e(u.case)}</a>`:''}${app?`<a class="${compact?'case-link':'showcase-button'}" href="${e(app)}" target="_blank" rel="noopener noreferrer">${e(p.id==='3deasy'?u.site:t.app)}</a>`:''}${source&&!compact?`<a class="case-link" href="${e(source)}" target="_blank" rel="noopener noreferrer">${e(t.source)}</a>`:''}</div>`
}
function projectDemoAccounts(p){
  if(!p.demoAccounts?.length)return '';
  const u=projectUi[lang];
  return `<div class="demo-accounts"><div class="demo-heading"><strong>${e(u.demo)}</strong><p>${e(u.demoIntro)}</p></div><div class="demo-grid">${p.demoAccounts.map(account=>`<div class="demo-account"><span class="demo-language">${e(account.language==='pt'?u.demoPt:u.demoEn)}</span><dl><div><dt>${e(u.email)}</dt><dd><code>${e(account.email)}</code></dd></div><div><dt>${e(u.password)}</dt><dd><code>${e(account.password)}</code></dd></div></dl></div>`).join('')}</div></div>`
}
